/// Synchronous SMB2/3 client built directly on the ffigen-generated
/// libsmb2 bindings.
///
/// This is the single Dart layer above `lib/src/ffi/libsmb2_bindings.dart`
/// (purely generated by ffigen). It owns everything the public API needs
/// and the generated bindings don't provide: the `smb2_context*`
/// lifecycle, path NUL validation, error → typed exception classification,
/// POSIX open-flag dispatch, and pipelined chunked pread/pwrite.
///
/// There is no intermediate C wrapper *and no dependency on libsmb2's own
/// sync wrappers*: every operation is started through the upstream
/// `*_async` API and driven to completion by the Dart-side event pump in
/// `lib/src/ffi/event_pump.dart`. This is what lets the package link
/// against **unmodified upstream libsmb2** — see the pump's docs for the
/// two sync-wrapper bugs (EINTR aborts, swallowed completion statuses)
/// that previously required patched binaries.
///
/// **Thread-safety caveat**: `smb2_init_context` / `smb2_destroy_context`
/// mutate a global `active_contexts` linked list in libsmb2's `init.c`
/// without internal locking, so concurrent calls from multiple isolates
/// can corrupt it. The mitigation is purely Dart-side ordering:
/// `Smb2Pool.connect` spawns its workers sequentially, so at most one
/// isolate is inside `smb2_init_context` at a time within a pool. Building
/// multiple pools concurrently, or running parallel
/// `Isolate.run(() => client.listShares(...))`, is still unprotected.
library;

import 'dart:collection' show ListQueue;
import 'dart:ffi';
import 'dart:io' show Platform;
import 'dart:math' show min;
import 'dart:typed_data';

import 'package:ffi/ffi.dart';

import 'ffi/event_pump.dart';
import 'ffi/libsmb2_bindings.dart';
import 'ffi/native_lib.dart';
import 'ffi/native_lifecycle.dart';
import 'smb2_error_type.dart';
import 'smb2_exceptions.dart';
import 'smb2_types.dart';

/// Opaque handle to an open file on a [Smb2Client].
///
/// Returned by [Smb2Client.openFileHandle] / [Smb2Client.openFileWithSize]
/// / [Smb2Client.openFileHandleWrite] and passed back to the handle-based
/// read/write/close methods. The underlying native pointer is not exposed
/// — callers never need to import `dart:ffi`.
class Smb2Handle {
  final Pointer<smb2fh> _fh;
  const Smb2Handle._(this._fh);

  /// Whether this handle wraps a non-null native pointer.
  bool get isValid => _fh != nullptr;
}

/// SMB2/3 client powered by libsmb2 via Dart FFI.
///
/// All operations are **synchronous** — run this client inside a
/// [Dart Isolate](https://api.dart.dev/stable/dart-isolate/Isolate-class.html)
/// to keep the UI responsive.
///
/// ```dart
/// final client = Smb2Client.open();
/// client.connect(host: '192.168.1.1', share: 'Music', user: 'guest');
/// final entries = client.listDirectory('');
/// client.disconnect();
/// ```
class Smb2Client implements Finalizable {
  final DynamicLibrary _lib;
  final LibSmb2Bindings _native;
  late final NativeLifecycle _lifecycle;
  late final Smb2EventPump _pump;
  late final Pointer<NativeFunction<Pointer<smb2_context> Function()>>
  _initContext;
  late final Pointer<NativeFunction<Void Function(Pointer<smb2_context>)>>
  _destroyContext;
  NativeSmb2Context? _context;

  Pointer<smb2_context> get _ctx =>
      _context?.pointer ?? nullptr.cast<smb2_context>();

  /// Timeout (seconds) applied to every operation on the connected
  /// context; mirrors the value passed to `smb2_set_timeout`. 0 = none.
  int _timeoutSeconds = 0;

  /// Reusable native staging area for pread/pwrite payloads. libsmb2 needs
  /// buffers that stay put while a request is in flight, so data can't go
  /// straight to/from the (moving) Dart heap; reusing one area avoids a
  /// malloc per call. Grows up to `_pipelineDepth × _maxRequestSize` and is
  /// released by [abort] (or a native finalizer, which also reports its size
  /// to the GC). Only ever used inside one synchronous call.
  final _NativeBuffer _staging = _NativeBuffer();

  Smb2Client._(this._lib) : _native = LibSmb2Bindings(_lib) {
    _lifecycle = NativeLifecycle(openLifecycleLibrary());
    _pump = Smb2EventPump(_native, _lifecycle);
    _initContext = _lib
        .lookup<NativeFunction<Pointer<smb2_context> Function()>>(
          'smb2_init_context',
        );
    _destroyContext = _lib
        .lookup<NativeFunction<Void Function(Pointer<smb2_context>)>>(
          'smb2_destroy_context',
        );
  }

  /// Create a client. The native library is resolved automatically via
  /// the Flutter plugin mechanism — no path arguments to wire up.
  factory Smb2Client.open() => Smb2Client._(openLibSmb2());

  /// Whether this client is connected to a share.
  bool get isConnected => _ctx != nullptr;

  // ─── Share enumeration ───────────────────────────────────────────────────

  /// List available shares on a server.
  ///
  /// This does **not** require an existing connection — it connects to `IPC$`
  /// internally, enumerates shares, and disconnects.
  ///
  /// **Thread-safety caveat**: allocates its own libsmb2 context, so the
  /// `active_contexts` race described in the library docs applies. Call it
  /// once at startup rather than concurrently from many isolates.
  ///
  /// Returns a list of [Smb2ShareInfo] with name and type.
  ///
  /// [seal]/[signing] mirror [connect]'s same-named parameters and are
  /// applied to the temporary IPC$ context used for enumeration.
  List<Smb2ShareInfo> listShares({
    required String host,
    String? user,
    String? password,
    String? domain,
    int timeoutSeconds = 30,
    bool seal = false,
    bool signing = false,
  }) {
    final context = _createContext(
      'Failed to create SMB2 context for share enumeration',
    );
    final ctx = context.pointer;

    try {
      _applyCredentials(
        _native,
        ctx,
        user: user,
        password: password,
        domain: domain,
        timeoutSeconds: timeoutSeconds,
      );
      if (seal) _native.smb2_set_seal(ctx, 1);
      if (signing) _native.smb2_set_sign(ctx, 1);

      // Connect to IPC$ (the named-pipe transport for SRVSVC). `user` is
      // passed through verbatim — libsmb2 treats an empty string as "guest".
      using((arena) {
        final pHost = host.toNativeUtf8(allocator: arena).cast<Char>();
        final pIpc = r'IPC$'.toNativeUtf8(allocator: arena).cast<Char>();
        final pUser = (user ?? '').toNativeUtf8(allocator: arena).cast<Char>();
        final res = _pump.run(
          context,
          opName: 'Connect to IPC\$ failed',
          start: (cb, cbData) => _native.smb2_connect_share_async(
            ctx,
            pHost,
            pIpc,
            pUser,
            cb,
            cbData,
          ),
          timeoutSeconds: timeoutSeconds,
        );
        if (res.status < 0) {
          throw _makeError(ctx, 'Connect to IPC\$ failed', -res.status);
        }
      });

      try {
        // SHARE_INFO_1 is value 1 in libsmb2's header — pass the typed enum
        // so it survives any future re-ordering of values upstream.
        final res = _pump.run(
          context,
          opName: 'Share enumeration failed',
          start: (cb, cbData) => _native.smb2_share_enum_async(
            ctx,
            SHARE_INFO_enum.SHARE_INFO_1,
            cb,
            cbData,
          ),
          timeoutSeconds: timeoutSeconds,
        );
        if (res.status < 0 || res.data == nullptr) {
          throw _makeError(ctx, 'Share enumeration failed', -res.status);
        }
        final rep = res.data.cast<srvsvc_NetrShareEnum_rep>();

        try {
          // Anonymous unions in C are wrapped by ffigen as an extra
          // synthetic `unnamed` field. The path is:
          //   rep.ses.ShareInfo.unnamed.Level1.{EntriesRead, Buffer}
          //   Buffer.share_info_1 → array of SHARE_INFO_1
          final container = rep.ref.ses.ShareInfo.unnamed.Level1;
          final count = container.EntriesRead;
          final buffer = container.Buffer;
          if (count == 0 || buffer == nullptr) return const <Smb2ShareInfo>[];

          final infosBase = buffer.ref.share_info_1;
          final results = <Smb2ShareInfo>[];
          for (var i = 0; i < count; i++) {
            final info = (infosBase + i).ref;
            final namePtr = info.netname.utf8;
            final name = namePtr == nullptr
                ? ''
                : namePtr.cast<Utf8>().toDartString();
            results.add(Smb2ShareInfo(name: name, type: info.type));
          }
          return results;
        } finally {
          // `smb2_free_data` recursively frees the entire response tree
          // (containers + carrays + utf16 string buffers) the DCE/RPC
          // decoder allocated.
          _native.smb2_free_data(ctx, rep.cast());
        }
      } finally {
        _disconnectQuiet(context);
      }
    } finally {
      context.abort();
    }
  }

  // ─── Connection ─────────────────────────────────────────────────────────

  /// Connect to an SMB share.
  ///
  /// Paths in subsequent calls are **relative to the share root**.
  /// Use `''` (empty string) to refer to the share root — not `/`.
  ///
  /// Throws [Smb2Exception] on failure.
  void connect({
    required String host,
    required String share,
    String? user,
    String? password,
    String? domain,
    int timeoutSeconds = 30,
    bool seal = false,
    bool signing = false,
    Smb2Version version = Smb2Version.any,
  }) {
    if (isConnected) disconnect();

    final context = _createContext('Failed to create SMB2 context');
    final ctx = context.pointer;

    try {
      _applyCredentials(
        _native,
        ctx,
        user: user,
        password: password,
        domain: domain,
        timeoutSeconds: timeoutSeconds,
      );
      if (seal) _native.smb2_set_seal(ctx, 1);
      if (signing) _native.smb2_set_sign(ctx, 1);
      if (version.value != 0) {
        _native.smb2_set_version(
          ctx,
          smb2_negotiate_version.fromValue(version.value),
        );
      }

      using((arena) {
        final pHost = host.toNativeUtf8(allocator: arena).cast<Char>();
        final pShare = share.toNativeUtf8(allocator: arena).cast<Char>();
        final pUser = (user ?? '').toNativeUtf8(allocator: arena).cast<Char>();
        final res = _pump.run(
          context,
          opName: 'Connect failed',
          start: (cb, cbData) => _native.smb2_connect_share_async(
            ctx,
            pHost,
            pShare,
            pUser,
            cb,
            cbData,
          ),
          timeoutSeconds: timeoutSeconds,
        );
        if (res.status < 0) {
          throw _makeError(ctx, 'Connect failed', -res.status);
        }
      });
    } catch (_) {
      context.abort();
      rethrow;
    }

    _context = context;
    _timeoutSeconds = timeoutSeconds;
  }

  /// Disconnect from the share and release all resources.
  ///
  /// Sends a wire-level logoff (`smb2_disconnect_share_async`) so the
  /// server can reclaim the session, then frees the local context.
  void disconnect() {
    final context = _context;
    if (context == null) return;
    try {
      if (context.isAlive) _disconnectQuiet(context);
    } finally {
      abort();
    }
  }

  /// Immediately releases the local context without waiting for the server.
  /// Safe to call repeatedly. The client may be connected again afterwards.
  void abort() {
    final context = _context;
    _context = null;
    context?.abort();
    // The context is gone, so no request can still target the staging area.
    _staging.release();
  }

  /// Best-effort wire-level logoff. Failures are swallowed — the caller
  /// destroys the context right after, which releases everything locally.
  void _disconnectQuiet(NativeSmb2Context context) {
    final ctx = context.pointer;
    try {
      // Completion status is ignored — nothing actionable on a failed
      // logoff; the caller destroys the context right after.
      _pump.run(
        context,
        opName: 'Disconnect',
        start: (cb, cbData) =>
            _native.smb2_disconnect_share_async(ctx, cb, cbData),
        // Never hang a teardown path on a dead server.
        timeoutSeconds: _disconnectTimeoutSeconds,
      );
    } on Smb2Exception {
      // Best effort only.
    }
  }

  /// Send a keepalive echo to the server.
  ///
  /// Returns normally if the connection is healthy.
  /// Throws [Smb2Exception] if the server is unreachable or the
  /// connection has been lost.
  void echo() {
    _ensureConnected();
    _checkedOp(
      'Echo failed',
      (cb, cbData) => _native.smb2_echo_async(_ctx, cb, cbData),
    );
  }

  // ─── Directory listing ──────────────────────────────────────────────────

  /// List all entries in a directory.
  ///
  /// [path] is relative to the share root. Use `''` for the root directory.
  /// Returns entries with name, type, size, and timestamps — no additional
  /// per-entry round-trips required.
  ///
  /// Throws [Smb2Exception] if the directory cannot be opened.
  List<Smb2DirEntry> listDirectory(String path) {
    _ensureConnected();
    // smb2_opendir_async fetches the complete listing; smb2_readdir /
    // smb2_closedir below only walk / free that in-memory snapshot (no
    // further network I/O, so no pump involvement).
    final dir = using((arena) {
      final p = _path(path, arena);
      final res = _op(
        'Failed to list directory',
        (cb, cbData) => _native.smb2_opendir_async(_ctx, p, cb, cbData),
      );
      if (res.status < 0 || res.data == nullptr) {
        throw _makeError(_ctx, 'Failed to list directory', -res.status);
      }
      return res.data.cast<smb2dir>();
    });

    try {
      final results = <Smb2DirEntry>[];
      while (true) {
        final ent = _native.smb2_readdir(_ctx, dir);
        if (ent == nullptr) break;
        // smb2_readdir returns a pointer into libsmb2-owned memory that is
        // recycled on the next call — copy what we need immediately.
        final e = ent.ref;
        final namePtr = e.name.cast<Uint8>();
        if (_isDotEntry(namePtr)) continue; // skip without decoding
        results.add(
          Smb2DirEntry(
            name: namePtr.cast<Utf8>().toDartString(),
            stat: _statFromNative(e.st),
          ),
        );
      }
      return results;
    } finally {
      _native.smb2_closedir(_ctx, dir);
    }
  }

  // ─── File reading ───────────────────────────────────────────────────────

  /// Read [length] bytes from a file at [offset].
  ///
  /// Ideal for reading partial content without downloading the entire file.
  ///
  /// Throws [Smb2Exception] on read failure.
  Uint8List readFileRange(String path, {int offset = 0, required int length}) {
    _ensureConnected();
    if (length < 0) throw _negativeReadLength();
    final fh = _openHandle(path, _flags.rdonly, 'Open failed');
    try {
      return _readBytes(fh, offset, length, 'Read failed');
    } finally {
      _closeQuiet(fh);
    }
  }

  /// Read an entire file into memory.
  ///
  /// Sizes the buffer with `fstat` on the open handle, then reads it with
  /// several `pread` requests in flight at once (sized by the negotiated
  /// MaxReadSize). For large files prefer [readFileRange] to read only the
  /// bytes you need.
  ///
  /// Throws [Smb2Exception] on failure.
  Uint8List readFile(String path) {
    _ensureConnected();
    final fh = _openHandle(path, _flags.rdonly, 'Open failed');

    try {
      // Size up-front via fstat on the handle we just opened — avoids a
      // second path-based round-trip (and its TOCTOU window).
      final size = _fstatSize(fh, 'Read file failed (fstat)');
      final out = Uint8List(size);

      // Each completed request is copied once, from the staging area
      // straight into [out]. A short return means EOF (file shrunk);
      // re-check with another read in case it grew back meanwhile.
      var offset = 0;
      while (offset < size) {
        final n = _preadInto(
          fh,
          offset,
          size - offset,
          out,
          offset,
          'Read file failed',
        );
        if (n == 0) break; // unexpected EOF — file shrunk mid-read
        offset += n;
      }
      // Trim if the file shrunk between fstat and the pread loop.
      return offset == size ? out : Uint8List.sublistView(out, 0, offset);
    } finally {
      _closeQuiet(fh);
    }
  }

  // ─── File info ──────────────────────────────────────────────────────────

  /// Get file or directory metadata without opening the file.
  ///
  /// Uses an SMB2 compound request internally (Create + QueryInfo + Close)
  /// so it completes in a single network round-trip.
  ///
  /// Throws [Smb2Exception] on failure.
  Smb2Stat stat(String path) {
    _ensureConnected();
    return using((arena) {
      final out = arena<smb2_stat_64>();
      final p = _path(path, arena);
      _checkedOp(
        'Stat failed',
        (cb, cbData) => _native.smb2_stat_async(_ctx, p, out, cb, cbData),
      );
      return _statFromNative(out.ref);
    });
  }

  /// Get the size of a file in bytes without opening it.
  ///
  /// Throws [Smb2Exception] on failure.
  int fileSize(String path) {
    _ensureConnected();
    return using((arena) {
      final out = arena<smb2_stat_64>();
      final p = _path(path, arena);
      _checkedOp(
        'File size failed',
        (cb, cbData) => _native.smb2_stat_async(_ctx, p, out, cb, cbData),
      );
      return out.ref.smb2_size;
    });
  }

  /// Get filesystem statistics (total/free space, block sizes).
  ///
  /// [path] can be any path on the share — typically `''` for the share root.
  ///
  /// Throws [Smb2Exception] on failure.
  Smb2StatVfs statvfs(String path) {
    _ensureConnected();
    return using((arena) {
      final out = arena<Smb2StatVfsNative>();
      final p = _path(path, arena);
      _checkedOp(
        'Statvfs failed',
        (cb, cbData) => _native.smb2_statvfs_async(_ctx, p, out, cb, cbData),
      );
      final s = out.ref;
      return Smb2StatVfs(
        blockSize: s.f_bsize,
        fragmentSize: s.f_frsize,
        totalBlocks: s.f_blocks,
        freeBlocks: s.f_bfree,
        availableBlocks: s.f_bavail,
        maxNameLength: s.f_namemax,
      );
    });
  }

  /// Read the target path of a symbolic link.
  ///
  /// The target string handed to the completion callback is owned by
  /// libsmb2 and freed the moment the callback returns — the pump's
  /// `capture` hook copies it into a Dart string while it is still valid.
  ///
  /// Throws [Smb2Exception] on failure (e.g., path is not a symlink).
  String readlink(String path) {
    _ensureConnected();
    return using((arena) {
      final p = _path(path, arena);
      final res = _op(
        'Readlink failed',
        (cb, cbData) => _native.smb2_readlink_async(_ctx, p, cb, cbData),
        copyCString: true,
      );
      if (res.status < 0) {
        throw _makeError(_ctx, 'Readlink failed', -res.status);
      }
      return res.captured ?? '';
    });
  }

  /// Check whether a file or directory exists.
  ///
  /// Returns `true` if the path exists, `false` if it does not.
  /// Throws [Smb2Exception] on connection or permission errors.
  bool exists(String path) {
    _ensureConnected();
    return using((arena) {
      final out = arena<smb2_stat_64>();
      final p = _path(path, arena);
      final res = _op(
        'Stat failed',
        (cb, cbData) => _native.smb2_stat_async(_ctx, p, out, cb, cbData),
      );
      if (res.status >= 0) return true; // no Smb2Stat materialized
      // Same classification as stat()'s exception, but the common
      // "not found" answer comes from errno alone — no error-string read
      // and no exception object on that path.
      final errno = -res.status;
      if (Smb2ErrorType.fromErrno(errno) == Smb2ErrorType.fileNotFound) {
        return false;
      }
      final error = _makeError(_ctx, 'Stat failed', errno);
      if (error.type == Smb2ErrorType.fileNotFound) return false;
      throw error;
    });
  }

  // ─── File handles (open once, read many, close once) ─────────────────

  /// Open a file for reading and return a reusable handle.
  ///
  /// Use [readHandle] to read from the handle, then [closeHandle] when done.
  /// This avoids repeated open/close network round-trips when reading
  /// multiple ranges from the same file.
  ///
  /// Throws [Smb2Exception] if the file cannot be opened.
  Smb2Handle openFileHandle(String path) {
    _ensureConnected();
    return Smb2Handle._(_openHandle(path, _flags.rdonly, 'Open failed'));
  }

  /// Open a file and get its size in one call.
  ///
  /// Saves a round-trip compared to calling [fileSize] + [openFileHandle]
  /// separately. Returns `(handle, fileSize)`.
  ///
  /// Throws [Smb2Exception] on failure.
  (Smb2Handle handle, int size) openFileWithSize(String path) {
    _ensureConnected();
    final fh = _openHandle(path, _flags.rdonly, 'Open failed');
    try {
      final size = _fstatSize(fh, 'Open failed (fstat)');
      return (Smb2Handle._(fh), size);
    } catch (_) {
      _closeQuiet(fh);
      rethrow;
    }
  }

  /// Read up to [length] bytes at [offset] from an open file handle.
  ///
  /// Lengths above the negotiated MaxReadSize are split into several
  /// requests kept in flight concurrently and the result is shorter than
  /// [length] only at EOF. A length within one request is a single
  /// `pread`, whose reply may be short (EOF or a server-side clamp) —
  /// as before; callers looping over a file should advance by the
  /// returned length.
  ///
  /// The handle must have been obtained from [openFileHandle] or
  /// [openFileWithSize].
  Uint8List readHandle(
    Smb2Handle handle, {
    int offset = 0,
    required int length,
  }) {
    _ensureConnected();
    if (length < 0) throw _negativeReadLength();
    return _readBytes(handle._fh, offset, length, 'Handle read failed');
  }

  /// Close a file handle opened with [openFileHandle] or [openFileWithSize].
  void closeHandle(Smb2Handle handle) {
    if (_ctx == nullptr || handle._fh == nullptr) return;
    _closeQuiet(handle._fh);
  }

  // ─── Streaming ──────────────────────────────────────────────────────

  /// Read a file in chunks without loading everything into RAM.
  ///
  /// Yields [Uint8List] chunks of up to [chunkSize] bytes.
  /// Uses a file handle internally — opens once, reads sequentially, closes.
  ///
  /// Throws [Smb2Exception] ([Smb2ErrorType.io]) if the file shrinks while
  /// it is being read, instead of yielding a silently truncated stream.
  Iterable<Uint8List> readFileChunked(
    String path, {
    int chunkSize = 1024 * 1024,
  }) sync* {
    if (chunkSize <= 0) {
      throw const Smb2Exception(
        'chunkSize must be positive',
        22,
        Smb2ErrorType.invalidParam,
      );
    }
    final (handle, size) = openFileWithSize(path);
    try {
      var offset = 0;
      while (offset < size) {
        final remaining = size - offset;
        final chunk = readHandle(
          handle,
          offset: offset,
          length: remaining < chunkSize ? remaining : chunkSize,
        );
        // Mirrors Smb2Pool.streamFile: 0 bytes before [size] means the file
        // was truncated by another client mid-stream.
        if (chunk.isEmpty) {
          throw Smb2Exception(
            'File shrank mid-stream: expected $size bytes, got $offset',
            null,
            Smb2ErrorType.io,
          );
        }
        // Advance by what actually arrived — a reply can be shorter than
        // requested, and skipping ahead would silently drop bytes.
        offset += chunk.length;
        yield chunk;
      }
    } finally {
      closeHandle(handle);
    }
  }

  // ─── File writing ───────────────────────────────────────────────────────

  /// Write [data] to a file at [offset], creating it if it doesn't exist.
  ///
  /// Ideal for writing partial content or appending to a file.
  ///
  /// Throws [Smb2Exception] on write failure.
  void writeFileRange(String path, Uint8List data, {int offset = 0}) {
    _ensureConnected();
    final fh = _openHandle(
      path,
      _flags.wronly | _flags.creat,
      'Open for write failed',
    );
    try {
      _pwriteAll(fh, data, offset);
    } finally {
      _closeQuiet(fh);
    }
  }

  /// Write [data] to a file, creating or truncating it.
  ///
  /// Replaces the entire file content with [data].
  ///
  /// Throws [Smb2Exception] on failure.
  void writeFile(String path, Uint8List data) {
    _ensureConnected();
    final fh = _openHandle(
      path,
      _flags.wronly | _flags.creat | _flags.trunc,
      'Open for write failed',
    );
    try {
      _pwriteAll(fh, data, 0);
    } finally {
      _closeQuiet(fh);
    }
  }

  // ─── Write handles (open once, write many, close once) ─────────────────

  /// Open a file for writing and return a reusable handle.
  ///
  /// The file is created if it doesn't exist.
  /// Use [writeHandle] to write, then [closeHandle] when done.
  ///
  /// Throws [Smb2Exception] if the file cannot be opened.
  Smb2Handle openFileHandleWrite(String path) {
    _ensureConnected();
    return Smb2Handle._(
      _openHandle(path, _flags.wronly | _flags.creat, 'Open for write failed'),
    );
  }

  /// Write [data] at [offset] to an open file handle.
  ///
  /// The handle must have been obtained from [openFileHandleWrite].
  void writeHandle(Smb2Handle handle, Uint8List data, {int offset = 0}) {
    _ensureConnected();
    _pwriteAll(handle._fh, data, offset);
  }

  /// Flush all buffered writes on a file handle to the server.
  ///
  /// Ensures all previously written data is persisted on the remote disk.
  /// The handle must have been obtained from [openFileHandleWrite].
  ///
  /// Throws [Smb2Exception] on failure.
  void fsync(Smb2Handle handle) {
    _ensureConnected();
    _checkedOp(
      'Fsync failed',
      (cb, cbData) => _native.smb2_fsync_async(_ctx, handle._fh, cb, cbData),
    );
  }

  /// Truncate an open file handle to [length] bytes.
  ///
  /// [length] must be non-negative.
  /// Throws [Smb2Exception] on failure.
  void ftruncate(Smb2Handle handle, int length) {
    _ensureConnected();
    if (length < 0) throw _negativeLength();
    _checkedOp(
      'Ftruncate failed',
      (cb, cbData) =>
          _native.smb2_ftruncate_async(_ctx, handle._fh, length, cb, cbData),
    );
  }

  // ─── Streaming write ────────────────────────────────────────────────────

  /// Write data from [chunks] to a file without loading everything into RAM.
  ///
  /// Creates or truncates the file, then writes each chunk sequentially.
  /// Uses a write handle internally — opens once, writes sequentially, closes.
  ///
  /// Consecutive chunks are coalesced into MaxWriteSize-sized requests and
  /// several requests stay in flight while the next chunks are produced.
  /// The staging area is private to this call, so [chunks] may itself use
  /// this client (e.g. to stream another file).
  void writeFileChunked(String path, Iterable<Uint8List> chunks) {
    final handle = openFileHandleWrite(path);
    try {
      ftruncate(handle, 0);
      final context = _liveContext();
      final requestSize = _requestSize(
        _native.smb2_get_max_write_size(context.pointer),
      );
      final staging = malloc<Uint8>(requestSize * _pipelineDepth);
      try {
        final stream = _PwriteStream(
          this,
          context,
          handle._fh,
          staging,
          requestSize,
          _pipelineDepth,
          0,
        );
        try {
          for (final chunk in chunks) {
            stream.add(chunk);
          }
          stream.close();
        } catch (_) {
          stream.cancel();
          rethrow;
        }
      } finally {
        // Every request is complete, drained, or died with the context.
        malloc.free(staging);
      }
    } finally {
      closeHandle(handle);
    }
  }

  // ─── File/directory management ─────────────────────────────────────────

  /// Delete a file.
  ///
  /// Throws [Smb2Exception] if the file cannot be deleted.
  void deleteFile(String path) {
    _ensureConnected();
    using((arena) {
      final p = _path(path, arena);
      _checkedOp(
        'Delete failed',
        (cb, cbData) => _native.smb2_unlink_async(_ctx, p, cb, cbData),
      );
    });
  }

  /// Create a directory.
  ///
  /// Throws [Smb2Exception] if the directory cannot be created.
  void mkdir(String path) {
    _ensureConnected();
    using((arena) {
      final p = _path(path, arena);
      _checkedOp(
        'Mkdir failed',
        (cb, cbData) => _native.smb2_mkdir_async(_ctx, p, cb, cbData),
      );
    });
  }

  /// Delete an empty directory.
  ///
  /// Throws [Smb2Exception] if the directory cannot be removed.
  void rmdir(String path) {
    _ensureConnected();
    using((arena) {
      final p = _path(path, arena);
      _checkedOp(
        'Rmdir failed',
        (cb, cbData) => _native.smb2_rmdir_async(_ctx, p, cb, cbData),
      );
    });
  }

  /// Rename or move a file or directory.
  ///
  /// Both paths are validated for embedded NUL bytes.
  /// Throws [Smb2Exception] on failure.
  void rename(String oldPath, String newPath) {
    _ensureConnected();
    using((arena) {
      final pOld = _path(oldPath, arena);
      final pNew = _path(newPath, arena);
      _checkedOp(
        'Rename failed',
        (cb, cbData) => _native.smb2_rename_async(_ctx, pOld, pNew, cb, cbData),
      );
    });
  }

  /// Truncate a file to [length] bytes.
  ///
  /// [length] must be non-negative.
  /// Throws [Smb2Exception] on failure.
  void truncate(String path, int length) {
    _ensureConnected();
    if (length < 0) throw _negativeLength();
    using((arena) {
      final p = _path(path, arena);
      _checkedOp(
        'Truncate failed',
        (cb, cbData) =>
            _native.smb2_truncate_async(_ctx, p, length, cb, cbData),
      );
    });
  }

  // ─── Helpers ────────────────────────────────────────────────────────────

  NativeSmb2Context _createContext(String failureMessage) {
    try {
      return _lifecycle.create(_initContext, _destroyContext);
    } on StateError {
      throw Smb2Exception(failureMessage);
    }
  }

  void _ensureConnected() {
    if (_ctx == nullptr) {
      throw const Smb2Exception('Not connected. Call connect() first.');
    }
  }

  /// Run one async operation on the connected context.
  Smb2OpResult _op(
    String opName,
    int Function(smb2_command_cb cb, Pointer<Void> cbData) start, {
    bool copyCString = false,
  }) => _pump.run(
    _context ?? (throw const Smb2Exception('Not connected')),
    opName: opName,
    start: start,
    timeoutSeconds: _timeoutSeconds,
    copyCString: copyCString,
  );

  /// Run one async operation and throw on a negative completion status.
  /// Returns the (non-negative) status — the byte count for pread/pwrite.
  int _checkedOp(
    String opName,
    int Function(smb2_command_cb cb, Pointer<Void> cbData) start,
  ) {
    final res = _op(opName, start);
    if (res.status < 0) throw _makeError(_ctx, opName, -res.status);
    return res.status;
  }

  /// Open [path] with [flags]; returns the native file handle.
  Pointer<smb2fh> _openHandle(String path, int flags, String errPrefix) {
    return using((arena) {
      final p = _path(path, arena);
      final res = _op(
        errPrefix,
        (cb, cbData) => _native.smb2_open_async(_ctx, p, flags, cb, cbData),
      );
      if (res.status < 0 || res.data == nullptr) {
        throw _makeError(_ctx, errPrefix, -res.status);
      }
      return res.data.cast<smb2fh>();
    });
  }

  /// Best-effort close of a native file handle. Never throws — used in
  /// finally blocks where a close failure must not mask the real error.
  void _closeQuiet(Pointer<smb2fh> fh) {
    try {
      _op(
        'Close failed',
        (cb, cbData) => _native.smb2_close_async(_ctx, fh, cb, cbData),
      );
    } on Smb2Exception {
      // The context/transport is torn; the server reclaims the handle
      // when the session dies.
    }
  }

  /// The connected context, for operations that drive a [Smb2OpBatch].
  NativeSmb2Context _liveContext() {
    final context = _context;
    if (context == null || !context.isAlive) {
      throw const Smb2Exception('Not connected. Call connect() first.');
    }
    return context;
  }

  /// Per-request payload size: the negotiated MaxRead/MaxWriteSize, capped
  /// so a full pipeline window stays a few MiB of staging memory.
  static int _requestSize(int negotiated) => negotiated <= 0
      ? _ioChunkFallback
      : (negotiated < _maxRequestSize ? negotiated : _maxRequestSize);

  /// Read up to [length] bytes at [offset] into a new, exactly-sized Dart
  /// heap list (GC-accounted; no native memory outlives the call).
  Uint8List _readBytes(
    Pointer<smb2fh> fh,
    int offset,
    int length,
    String errPrefix,
  ) {
    if (length == 0) return Uint8List(0);
    final requestSize = _requestSize(_native.smb2_get_max_read_size(_ctx));
    if (length <= requestSize) {
      // Single request: read into the reusable staging area and copy out
      // exactly the bytes that arrived.
      final buf = _staging.acquire(length);
      final n = _checkedOp(
        errPrefix,
        (cb, cbData) =>
            _native.smb2_pread_async(_ctx, fh, buf, length, offset, cb, cbData),
      );
      if (n > length) throw _overlongReply(errPrefix, n, length);
      return Uint8List.fromList(buf.asTypedList(n));
    }
    final out = Uint8List(length);
    final n = _preadInto(fh, offset, length, out, 0, errPrefix);
    if (n == length) return out;
    // Short only at EOF: don't pin [length] bytes for a smaller result.
    return Uint8List.fromList(Uint8List.sublistView(out, 0, n));
  }

  /// Read up to [length] bytes at file [offset] into [out] at [outOffset],
  /// keeping up to [_pipelineDepth] pread requests in flight.
  ///
  /// Returns the number of bytes read. Requests that come back short (a
  /// libsmb2 credit/MaxReadSize clamp) are re-issued for their remainder,
  /// so the bytes delivered are always a contiguous prefix; the result is
  /// shorter than [length] only when a reply returned 0 bytes (EOF).
  int _preadInto(
    Pointer<smb2fh> fh,
    int offset,
    int length,
    Uint8List out,
    int outOffset,
    String errPrefix,
  ) {
    final context = _liveContext();
    final ctx = context.pointer;
    var requestSize = _requestSize(_native.smb2_get_max_read_size(ctx));
    final stride = length < requestSize ? length : requestSize;
    final depth = min(_pipelineDepth, (length + stride - 1) ~/ stride);
    final staging = _staging.acquire(stride * depth);
    final batch = _pump.batch(context, timeoutSeconds: _timeoutSeconds);
    final inFlight = ListQueue<_IoRequest>();

    void startRead(_IoRequest r) {
      r.slot = batch.start(
        errPrefix,
        (cb, cbData) => _native.smb2_pread_async(
          ctx,
          fh,
          r.buf,
          r.length,
          offset + r.pos,
          cb,
          cbData,
        ),
      );
    }

    var issued = 0; // bytes of the range already assigned to a request
    var seq = 0; // request counter → staging region (FIFO ring)
    try {
      while (true) {
        while (inFlight.length < depth && issued < length) {
          final len = min(requestSize, length - issued);
          final r = _IoRequest(staging + (seq++ % depth) * stride, issued, len);
          startRead(r);
          inFlight.add(r);
          issued += len;
        }
        if (inFlight.isEmpty) return length;

        final head = inFlight.first;
        final n = batch.wait(head.slot, errPrefix);
        if (n < 0) throw _makeError(ctx, errPrefix, -n);
        if (n > head.length) throw _overlongReply(errPrefix, n, head.length);
        if (n > 0) {
          final at = outOffset + head.pos;
          out.setRange(at, at + n, head.buf.asTypedList(n));
        }
        if (n == head.length) {
          inFlight.removeFirst();
          continue;
        }

        if (n == 0) {
          // EOF: later replies, if any, are beyond the delivered prefix —
          // drain them so the staging area is free again.
          inFlight.removeFirst();
          batch.cancel();
          return head.pos;
        }
        // Short reply (credit/MaxReadSize clamp, or the tail before EOF):
        // fetch the rest of this request in place — a 0-byte answer then
        // marks EOF — and size the following requests to what the server
        // actually serves.
        head.advance(n);
        if (n >= _minAdaptiveRequest && n < requestSize) requestSize = n;
        startRead(head);
      }
    } catch (_) {
      // Error statuses, pump failures, rejected starts: make sure nothing
      // still targets the staging area before it is reused.
      batch.cancel();
      rethrow;
    }
  }

  /// File size via fstat on an open handle.
  int _fstatSize(Pointer<smb2fh> fh, String errPrefix) {
    return using((arena) {
      final st = arena<smb2_stat_64>();
      _checkedOp(
        errPrefix,
        (cb, cbData) => _native.smb2_fstat_async(_ctx, fh, st, cb, cbData),
      );
      return st.ref.smb2_size;
    });
  }

  /// NUL-rejecting path allocation against [arena].
  ///
  /// libsmb2 takes a C `const char *`, so an embedded NUL silently
  /// truncates the path on the wire — a caller that builds a path from
  /// untrusted input could let a prefix short-circuit the suffix.
  Pointer<Char> _path(String path, Arena arena) {
    if (path.contains('\u0000')) {
      throw const Smb2Exception(
        'Invalid path: contains NUL byte',
        22,
        Smb2ErrorType.invalidParam,
      );
    }
    return path.toNativeUtf8(allocator: arena).cast();
  }

  /// Send all of [data] to handle [fh] starting at [offset].
  ///
  /// [data] is copied piecewise (one request at a time) into the reusable
  /// staging area — never duplicated in full — and up to [_pipelineDepth]
  /// pwrite requests of the negotiated `max_write_size` are kept in flight.
  void _pwriteAll(Pointer<smb2fh> fh, Uint8List data, int offset) {
    if (data.isEmpty) return;
    final context = _liveContext();
    final requestSize = _requestSize(
      _native.smb2_get_max_write_size(context.pointer),
    );
    final stride = data.length < requestSize ? data.length : requestSize;
    final depth = min(_pipelineDepth, (data.length + stride - 1) ~/ stride);
    final stream = _PwriteStream(
      this,
      context,
      fh,
      _staging.acquire(stride * depth),
      stride,
      depth,
      offset,
    );
    try {
      stream.add(data);
      stream.close();
    } catch (_) {
      stream.cancel();
      rethrow;
    }
  }

  /// Build a typed [Smb2Exception] for a failed operation.
  ///
  /// [errno] is the fresh `-status` from the operation's completion
  /// callback (or 0 when unavailable); classification prefers it and falls
  /// back to the context's message — see [Smb2ErrorType.classifyStatus].
  Smb2Exception _makeError(
    Pointer<smb2_context> ctx,
    String prefix,
    int errno,
  ) {
    final ptr = _native.smb2_get_error(ctx);
    final msg = ptr == nullptr
        ? 'Unknown error'
        : ptr.cast<Utf8>().toDartString();
    return Smb2Exception(
      '$prefix: $msg',
      errno,
      Smb2ErrorType.classifyStatus(errno, msg),
    );
  }
}

/// POSIX-style open flags as understood by `smb2_open_async` in libsmb2.
///
/// libsmb2 forwards the integer straight to the host OS's `<fcntl.h>`
/// interpretation, and the prebuilt per-platform binary was compiled
/// against that platform's `<fcntl.h>`. So the Dart side must use the
/// *host* OS's values, not a single "portable" set.
///
/// Values audited from:
///   * Linux/Android (glibc/bionic): O_CREAT=0o100, O_EXCL=0o200,
///     O_TRUNC=0o1000, O_APPEND=0o2000.
///   * macOS/iOS (Apple libc): O_APPEND=0x8, O_CREAT=0x200, O_TRUNC=0x400,
///     O_EXCL=0x800.
///   * Windows (MSVC / mingw-w64): O_APPEND=0x8, O_CREAT=0x100,
///     O_TRUNC=0x200, O_EXCL=0x400.
///
/// O_RDONLY/O_WRONLY/O_RDWR are 0/1/2 on every supported platform.
class _OpenFlags {
  final int rdonly;
  final int wronly;
  final int rdwr;
  final int creat;
  final int trunc;
  final int excl;
  final int append;

  const _OpenFlags({
    required this.rdonly,
    required this.wronly,
    required this.rdwr,
    required this.creat,
    required this.trunc,
    required this.excl,
    required this.append,
  });

  static const _linuxLike = _OpenFlags(
    rdonly: 0,
    wronly: 1,
    rdwr: 2,
    creat: 0x40,
    trunc: 0x200,
    excl: 0x80,
    append: 0x400,
  );

  static const _darwin = _OpenFlags(
    rdonly: 0,
    wronly: 1,
    rdwr: 2,
    creat: 0x200,
    trunc: 0x400,
    excl: 0x800,
    append: 0x8,
  );

  static const _windows = _OpenFlags(
    rdonly: 0,
    wronly: 1,
    rdwr: 2,
    creat: 0x100,
    trunc: 0x200,
    excl: 0x400,
    append: 0x8,
  );

  static _OpenFlags _resolve() {
    if (Platform.isLinux || Platform.isAndroid) return _linuxLike;
    if (Platform.isMacOS || Platform.isIOS) return _darwin;
    if (Platform.isWindows) return _windows;
    throw UnsupportedError(
      'dart_smb2: unsupported platform ${Platform.operatingSystem}',
    );
  }
}

final _OpenFlags _flags = _OpenFlags._resolve();

/// Cap on how long a best-effort wire logoff may block a teardown path.
const int _disconnectTimeoutSeconds = 5;

/// Fallback request size used when libsmb2 reports a MaxRead/WriteSize of 0.
const int _ioChunkFallback = 1024 * 1024;

/// Maximum pread/pwrite requests one call keeps in flight on a context.
/// Overlapping round trips is what lifts throughput on high-latency links;
/// libsmb2 itself holds back requests the server hasn't granted credits for.
const int _pipelineDepth = 4;

/// Upper bound for one pipelined request, so a full window stays within
/// `_pipelineDepth × 1 MiB` of staging memory even when the server
/// negotiates 8 MiB MaxRead/WriteSize.
const int _maxRequestSize = 1024 * 1024;

/// Requests are only shrunk to a clamped reply size at or above this, so a
/// tiny reply (e.g. a file shrinking under us) can't degrade the pipeline.
const int _minAdaptiveRequest = 64 * 1024;

Smb2Exception _negativeReadLength() => const Smb2Exception(
  'Read length must be non-negative',
  22,
  Smb2ErrorType.invalidParam,
);

Smb2Exception _overlongReply(String prefix, int got, int asked) =>
    Smb2Exception(
      '$prefix: server returned $got bytes for a $asked-byte request',
      5,
      Smb2ErrorType.io,
    );

/// Whether the NUL-terminated name at [name] is `.` or `..`.
bool _isDotEntry(Pointer<Uint8> name) =>
    name[0] == 0x2e && (name[1] == 0 || (name[1] == 0x2e && name[2] == 0));

/// One in-flight pread/pwrite: [length] bytes at range position [pos],
/// staged at [buf].
final class _IoRequest {
  _IoRequest(this.buf, this.pos, this.length);

  Pointer<Uint8> buf;
  int pos;
  int length;
  Pointer<Void> slot = nullptr;

  /// Drop the first [n] bytes (already transferred) from the request.
  void advance(int n) {
    buf += n;
    pos += n;
    length -= n;
  }
}

/// Sequential pipelined writer: appends caller bytes into fixed-size
/// staging regions, issuing one pwrite per full region, with at most
/// `depth` requests in flight. Regions are recycled strictly in FIFO
/// order, so a region is only refilled after its previous request has
/// completed.
final class _PwriteStream {
  _PwriteStream(
    this._client,
    NativeSmb2Context context,
    this._fh,
    this._staging,
    this._stride,
    this._depth,
    this._fileOffset,
  ) : _requestSize = _stride,
      _batch = _client._pump.batch(
        context,
        timeoutSeconds: _client._timeoutSeconds,
      );

  static const String _errPrefix = 'Write failed';

  final Smb2Client _client;
  final Pointer<smb2fh> _fh;
  final Pointer<Uint8> _staging;
  final int _stride;
  final int _depth;
  final Smb2OpBatch _batch;
  final ListQueue<_IoRequest> _inFlight = ListQueue<_IoRequest>();

  /// Bytes per request; may shrink if the server clamps writes.
  int _requestSize;

  /// File offset of the first byte in the open (not yet issued) region.
  int _fileOffset;

  /// Bytes buffered in the open region.
  int _fill = 0;

  /// Requests issued so far → staging region index.
  int _seq = 0;

  Pointer<Uint8> get _region => _staging + (_seq % _depth) * _stride;

  /// Append [data] to the stream.
  void add(Uint8List data) {
    var pos = 0;
    while (pos < data.length) {
      if (_fill == 0) {
        // About to reuse a region: its previous request must be done.
        while (_inFlight.length >= _depth) {
          _completeHead();
        }
      }
      final n = min(_requestSize - _fill, data.length - pos);
      _region.asTypedList(_fill + n).setRange(_fill, _fill + n, data, pos);
      _fill += n;
      pos += n;
      if (_fill == _requestSize) _issueOpen();
    }
  }

  /// Issue any buffered bytes and wait for every request to complete.
  void close() {
    if (_fill > 0) _issueOpen();
    while (_inFlight.isNotEmpty) {
      _completeHead();
    }
  }

  /// Error path: drain or abandon (by destroying the context) whatever is
  /// still in flight so the staging memory can be reused or freed.
  void cancel() {
    _inFlight.clear();
    _batch.cancel();
  }

  void _issueOpen() {
    final r = _IoRequest(_region, _fileOffset, _fill);
    _start(r);
    _inFlight.add(r);
    _fileOffset += _fill;
    _fill = 0;
    _seq++;
  }

  void _start(_IoRequest r) {
    final native = _client._native;
    final ctx = _client._ctx;
    final fh = _fh;
    r.slot = _batch.start(
      _errPrefix,
      (cb, cbData) =>
          native.smb2_pwrite_async(ctx, fh, r.buf, r.length, r.pos, cb, cbData),
    );
  }

  void _completeHead() {
    final head = _inFlight.first;
    final n = _batch.wait(head.slot, _errPrefix);
    if (n < 0) throw _client._makeError(_client._ctx, _errPrefix, -n);
    if (n > head.length) throw _overlongReply(_errPrefix, n, head.length);
    if (n == head.length) {
      _inFlight.removeFirst();
      return;
    }
    if (n == 0) {
      // The old sequential loop silently stopped here, leaving the file
      // short; surface it instead.
      throw Smb2Exception(
        '$_errPrefix: server accepted 0 of ${head.length} bytes '
        'at offset ${head.pos}',
        5,
        Smb2ErrorType.io,
      );
    }
    // Clamped write: send the remainder from the same region and use the
    // server's effective size for regions opened from now on.
    head.advance(n);
    if (n >= _minAdaptiveRequest && n < _requestSize && _fill == 0) {
      _requestSize = n;
    }
    _start(head);
  }
}

/// Grow-only native scratch buffer, freed explicitly by [release] or by a
/// native finalizer that also reports the allocation to the GC
/// (`externalSize`), unlike `Pointer.asTypedList(finalizer:)`.
final class _NativeBuffer implements Finalizable {
  static final NativeFinalizer _finalizer = NativeFinalizer(malloc.nativeFree);

  Pointer<Uint8> _ptr = nullptr;
  int _size = 0;

  /// A buffer of at least [size] bytes. Previous contents are not kept.
  Pointer<Uint8> acquire(int size) {
    if (size <= _size) return _ptr;
    release();
    final ptr = malloc<Uint8>(size);
    _finalizer.attach(this, ptr.cast(), detach: this, externalSize: size);
    _ptr = ptr;
    _size = size;
    return ptr;
  }

  /// Free the buffer now (it is re-allocated on the next [acquire]).
  void release() {
    if (_ptr == nullptr) return;
    _finalizer.detach(this);
    malloc.free(_ptr);
    _ptr = nullptr;
    _size = 0;
  }
}

Smb2Exception _negativeLength() => const Smb2Exception(
  'Truncate length must be non-negative',
  22,
  Smb2ErrorType.invalidParam,
);

Smb2FileType _parseType(int type) => switch (type) {
  SMB2_TYPE_DIRECTORY => Smb2FileType.directory,
  SMB2_TYPE_LINK => Smb2FileType.link,
  _ => Smb2FileType.file, // SMB2_TYPE_FILE (0) and any unexpected value.
};

/// Timestamps stay raw epoch seconds until first read — see [Smb2Stat].
Smb2Stat _statFromNative(smb2_stat_64 st) => smb2StatFromEpochSeconds(
  type: _parseType(st.smb2_type),
  size: st.smb2_size,
  modifiedSeconds: st.smb2_mtime,
  createdSeconds: st.smb2_btime,
);

/// Apply optional credentials + timeout to a freshly-created context before
/// connecting. Centralised so the connect and share-enum paths can't drift
/// on which setters are called and in what order.
void _applyCredentials(
  LibSmb2Bindings lib,
  Pointer<smb2_context> ctx, {
  String? user,
  String? password,
  String? domain,
  int timeoutSeconds = 0,
}) {
  using((arena) {
    if (user != null && user.isNotEmpty) {
      lib.smb2_set_user(ctx, user.toNativeUtf8(allocator: arena).cast());
    }
    if (password != null && password.isNotEmpty) {
      lib.smb2_set_password(
        ctx,
        password.toNativeUtf8(allocator: arena).cast(),
      );
    }
    if (domain != null && domain.isNotEmpty) {
      lib.smb2_set_domain(ctx, domain.toNativeUtf8(allocator: arena).cast());
    }
  });
  if (timeoutSeconds > 0) lib.smb2_set_timeout(ctx, timeoutSeconds);
}
